-- Compact, permission-independent smooth fallback. Full-resolution artwork is unchanged.
local encoded={["Jungle"]="",["GardenSize"]="",["Index"]="",["Storm"]="",["RobuxShop"]="",["GardenTime"]="",["City"]="",["Moon"]="",["Lava"]="",["Bolt"]="",["Crystal"]="",["WeatherClear"]="",["Money"]="",["WeatherRain"]="",["Forest"]="",["WeatherSnow"]="",["WeatherBlizzard"]="",["Gem"]="",["WeatherThunderstorm"]="",["Snow"]="",["Mech"]="",["Clover"]="",["Desert"]=""}
local function decode(s)
 return (s:gsub('..',function(pair)return string.char(tonumber(pair,16))end))
end
local cache={}
return setmetatable(cache,{__index=function(_,kind)
 local source=encoded[kind];if not source then return nil end
 local s=decode(source);local at=1
 local function byte()local v=s:byte(at);at+=1;return v end
 local width,height,colors=byte(),byte(),byte();local palette={}
 for i=1,colors do palette[i]={byte(),byte(),byte()}end
 local count=byte()+byte()*256;local strips={}
 for i=1,count do
  local x,y,w,n=byte(),byte(),byte(),byte();local keys={}
  for j=1,n do local t,index,alpha=byte(),byte(),byte();local c=palette[index+1];keys[j]={t/255,c[1],c[2],c[3],alpha}end
  strips[i]={x,y,w,keys}
 end
 assert(at==#s+1,'Invalid fallback artwork')
 local result={Width=width,Height=height,Strips=strips};rawset(cache,kind,result);return result
end})
